     * 操作前确认文案；空字符串表示跳过确认。
     * @default ""
     */
    confirmMessage?: string;
    /**
     * 操作前确认标题。
     * @default ""
     */
    confirmTitle?: string;
    /**
     * 操作前确认类型。
     * 由 UI 消息组件解释，常见值为 warning、info、success、error。
     * @default "warning"
     */
    confirmType?: string;
    /**
     * 静默模式；成功/失败提示不展示。
     * @default false
     */
    silent?: boolean;
    /**
